import threading

def rate_limit(leak_rate, capacity, clock):
    if leak_rate <= 0:
        raise ValueError("leak_rate must be positive")
    if capacity <= 0:
        raise ValueError("capacity must be positive")
    if not callable(clock):
        raise TypeError("clock must be callable")

    state = {"level": 0.0, "last_time": None}
    lock = threading.Lock()

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now = clock()
            with lock:
                if state["last_time"] is not None:
                    elapsed = max(0.0, now - state["last_time"])
                    state["level"] = max(
                        0.0, state["level"] - elapsed * leak_rate
                    )
                state["last_time"] = now

                if state["level"] + 1.0 <= capacity:
                    state["level"] += 1.0
                    admitted = True
                else:
                    admitted = False

            if not admitted:
                return False
            return func(*args, **kwargs)

        return wrapper

    return decorator

